  return value;
};
const text = (value, maximum, name) => {
  if (typeof value !== 'string' || !value.trim() || value.length > maximum)
    throw fault('SCHEDULE_TEXT_REQUIRED', 'Enter ' + name + '.');
  return value.trim();
