      retained.setupFile === join(expectedPath, 'setup.json'), 'RPC_COMMERCE_PREPARATION_NOT_CONFIGURED');
    const fresh = await reviewCommerceSetup({ configFile: retained.setupFile, directory: retained.preparedDirectory });
