      {stdio:['ignore','pipe','pipe',handle.fd],timeout:10000});
    need(!locked.error&&locked.status===0,locked.status===73?'WIRE_ATTEMPT_ACTIVE':'WIRE_FLOCK_REQUIRED');
    return handle;
