    if (!stat.isFile() || !named.isFile() || named.isSymbolicLink() ||
        (stat.mode & 0o077) || stat.dev !== named.dev || stat.ino !== named.ino)
      throw new Error('FLEET_PRIVATE_LEASE_REQUIRED');
  };
